<?php
declare(strict_types=1);
namespace App\Controllers\Front;
use App\Core\{Controller,Auth,Database as DB,Response,Validator};
use App\Services\LoginService;
final class AccountController extends Controller
{
    public function loginForm():void {$this->front('auth',['title'=>'Chào mừng trở lại','register'=>false]);}
    public function registerForm():void {$this->front('auth',['title'=>'Tạo tài khoản E-Shop','register'=>true]);}
    public function login():void {try{LoginService::attempt($_POST);Response::redirect('/account');}catch(\Throwable $e){$this->failure($e,'/login');}}
    public function register():void {try{$name=Validator::text($_POST['name']??'',2,120);$email=Validator::email($_POST['email']??'');$password=Validator::text($_POST['password']??'',10,72);if($password!==($_POST['password_confirmation']??'')){throw new \DomainException('Mật khẩu xác nhận không khớp.');}if(DB::execute('SELECT id FROM users WHERE email=?',[$email])->fetch()){throw new \DomainException('Email đã được đăng ký.');}DB::execute('INSERT INTO users(name,email,password_hash) VALUES (?,?,?)',[$name,$email,password_hash($password,PASSWORD_DEFAULT)]);Auth::login((int)DB::connection()->lastInsertId());Response::redirect('/account');}catch(\Throwable $e){$this->failure($e,'/register');}}
    public function logout():void {Auth::logout();unset($_SESSION['cart'],$_SESSION['checkout_token']);Response::redirect('/');}
    public function profile():void {$user=Auth::user();$this->front('account',['title'=>'Tài khoản của tôi','user'=>$user,'addresses'=>DB::execute('SELECT * FROM addresses WHERE user_id=? ORDER BY is_default DESC,id DESC',[$user['id']])->fetchAll()]);}
    public function update():void {try{$user=Auth::user();DB::execute('UPDATE users SET name=?,phone=? WHERE id=?',[Validator::text($_POST['name']??'',2,120),Validator::text($_POST['phone']??'',0,20),$user['id']]);flash('success','Đã cập nhật hồ sơ.');Response::redirect('/account');}catch(\Throwable $e){$this->failure($e,'/account');}}
    public function password():void {try{$user=Auth::user();$hash=DB::execute('SELECT password_hash FROM users WHERE id=?',[$user['id']])->fetchColumn();if(!password_verify((string)($_POST['current_password']??''),$hash)){throw new \DomainException('Mật khẩu hiện tại không đúng.');}$password=Validator::text($_POST['password']??'',10,72);if($password!==($_POST['password_confirmation']??'')){throw new \DomainException('Mật khẩu xác nhận không khớp.');}DB::execute('UPDATE users SET password_hash=? WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$user['id']]);session_regenerate_id(true);flash('success','Đã đổi mật khẩu.');Response::redirect('/account');}catch(\Throwable $e){$this->failure($e,'/account');}}
    public function address():void {try{$user=Auth::user();DB::transaction(static function()use($user):void{DB::execute('SELECT id FROM users WHERE id=? FOR UPDATE',[$user['id']]);$default=isset($_POST['is_default'])||!(int)DB::execute('SELECT COUNT(*) FROM addresses WHERE user_id=?',[$user['id']])->fetchColumn();if($default){DB::execute('UPDATE addresses SET is_default=0 WHERE user_id=?',[$user['id']]);}DB::execute('INSERT INTO addresses(user_id,recipient,phone,address_line,is_default) VALUES (?,?,?,?,?)',[$user['id'],Validator::text($_POST['recipient']??'',2,120),Validator::text($_POST['phone']??'',8,20),Validator::text($_POST['address_line']??'',10,500),(int)$default]);});Response::redirect('/account');}catch(\Throwable $e){$this->failure($e,'/account');}}
    public function addressAction(string $id):void {try{$user=Auth::user();DB::transaction(static function()use($user,$id):void{DB::execute('SELECT id FROM users WHERE id=? FOR UPDATE',[$user['id']]);$address=DB::execute('SELECT * FROM addresses WHERE id=? AND user_id=?',[$id,$user['id']])->fetch();if(!$address){throw new \DomainException('Địa chỉ không tồn tại.');}if(($_POST['action']??'')==='delete'){DB::execute('DELETE FROM addresses WHERE id=? AND user_id=?',[$id,$user['id']]);if($address['is_default']){$next=DB::execute('SELECT id FROM addresses WHERE user_id=? ORDER BY id LIMIT 1',[$user['id']])->fetchColumn();if($next){DB::execute('UPDATE addresses SET is_default=1 WHERE id=?',[$next]);}}}else{DB::execute('UPDATE addresses SET is_default=0 WHERE user_id=?',[$user['id']]);DB::execute('UPDATE addresses SET is_default=1 WHERE id=? AND user_id=?',[$id,$user['id']]);}});Response::redirect('/account');}catch(\Throwable $e){$this->failure($e,'/account');}}
}
